import {loadRules,formatEntries} from './rules-library.mjs';
import {blankRule,starterRule,ruleId,ruleProblems,damageTypes,conditions,triggers} from './spell-rule-schema.mjs';
import {loadSpellRules,saveSpellRule,removeSpellRule,importSpellRules} from './spell-rule-store.mjs';
import {knownRooms} from './adventure-rooms.mjs';
import {readSession,writeSession} from './multiplayer.mjs';
import {makeActor,newBattle,castSpell,startInitiative,endTurn,exploreToken} from './combat.mjs';
import {customSpellCells,moveCustomSphere} from './custom-spells.mjs';
import {escape} from './format.mjs';
const draftKey='wayfarer-spell-rule-drafts-v1';
const option=(value,label,selected)=>`<option value="${escape(value)}"${selected?' selected':''}>${escape(label)}</option>`;
const input=(label,path,value,{type='number',min=0,max=600}={})=>`<label>${escape(label)}<input data-rule-field="${path}" type="${type}" value="${escape(value)}"${type==='number'?` min="${min}" max="${max}"`:''}></label>`;
const select=(label,path,value,choices)=>`<label>${escape(label)}<select data-rule-field="${path}">${choices.map(choice=>{const [key,name]=Array.isArray(choice)?choice:[choice,choice];return option(key,name,value===key);}).join('')}</select></label>`;
const check=(label,path,value)=>`<label class="rule-check"><input type="checkbox" data-rule-field="${path}"${value?' checked':''}>${escape(label)}</label>`;
export async function mountSpellRuleEditor(host){
 host.innerHTML='<p>Loading source spells…</p>';let catalog;try{catalog=(await loadRules()).spells;}catch(error){host.textContent=error.message;return;}if(!host.isConnected)return;
 let saved=loadSpellRules(),drafts={},selected,rule,query='',filter='all',preview;
 try{drafts=JSON.parse(localStorage.getItem(draftKey)||'{}');}catch{}
 const retain=()=>{if(!rule)return;drafts[rule.reference]=structuredClone(rule);try{localStorage.setItem(draftKey,JSON.stringify(drafts));}catch{}};
 const status=text=>{const element=host.querySelector('.rule-status');if(element)element.textContent=text;};
 function choose(spell){retain();selected=spell;rule=structuredClone(drafts[ruleId(spell)] ?? saved[ruleId(spell)] ?? starterRule(spell));preview=null;render();}
 function summary(){const p=ruleProblems(rule),target=host.querySelector('.rule-validation');if(target)target.textContent=p.length?p.join(' '):'Ready to test and save.';host.querySelector('[data-rule-action=save]')?.toggleAttribute('disabled',p.length>0);}
 function library(){
 const matches=catalog.filter(spell=>(filter==='all'||filter===spell.edition||filter==='saved'&&saved[ruleId(spell)])&&(!query||(spell.name+' '+spell.source).toLowerCase().includes(query.toLowerCase())));
 host.querySelector('.rule-spell-list').innerHTML=matches.slice(0,80).map(spell=>`<button type="button" data-rule-select="${escape(ruleId(spell))}" aria-pressed="${rule?.reference===ruleId(spell)}"><strong>${escape(spell.name)}</strong><small>${escape(spell.source)} · ${escape(spell.edition)} · ${spell.level?'Level '+spell.level:'Cantrip'}${saved[ruleId(spell)]?' · Saved':''}</small></button>`).join('')||'<p>No matching spells.</p>';
 host.querySelector('.rule-search-count').textContent=matches.length>80?`Showing 80 of ${matches.length}. Search to narrow the list.`:`${matches.length} matching spells`;
 }
 function effects(){return rule.effects.map((effect,i)=>`<fieldset class="rule-effect"><legend>Effect ${i+1}</legend><div class="rule-fields">
 ${select('When','effects.'+i+'.trigger',effect.trigger,triggers.map(key=>[key,{cast:'On cast',enter:'First entry each turn',start:'Start of turn',end:'End of turn',ram:'Sphere rams a creature'}[key]]))}
 ${select('Affected area','effects.'+i+'.area',effect.area,[['footprint','Spell footprint'],['nearby','Within nearby distance'],['hotSide','Wall + chosen hot side']])}
 ${select('Saving throw','effects.'+i+'.save',effect.save,[['','No save'],...['str','dex','con','int','wis','cha'].map(key=>[key,key.toUpperCase()])])}
 ${select('On successful save','effects.'+i+'.onSave',effect.onSave,[['half','Half damage'],['none','No damage']])}
 ${select('Condition on failed save','effects.'+i+'.condition',effect.condition,conditions.map(value=>[value,value||'No condition']))}</div>
 ${effect.damage.map((damage,j)=>`<div class="rule-damage-row">${input('Damage dice',`effects.${i}.damage.${j}.formula`,damage.formula,{type:'text'})}${select('Damage type',`effects.${i}.damage.${j}.type`,damage.type,damageTypes)}${input('Extra per slot above base',`effects.${i}.damage.${j}.upcast`,damage.upcast,{type:'text'})}<button type="button" class="button outline small" data-rule-action="remove-damage" data-index="${i}" data-component="${j}">Remove damage</button></div>`).join('')}
 <div class="rule-buttons"><button type="button" class="button outline small" data-rule-action="add-damage" data-index="${i}">Add damage type</button><button type="button" class="button outline small" data-rule-action="remove-effect" data-index="${i}">Remove effect</button></div></fieldset>`).join('');}
 function render(){
 host.innerHTML=`<section class="spell-rule-desk" aria-label="Spell rules editor"><header class="rule-page-heading"><div><h1>Spell rules</h1><p>Build reusable spell effects here. Adventure rooms run a saved copy.</p></div><div class="rule-buttons"><button class="button outline small" type="button" data-rule-action="export">Export rules</button><button class="button outline small" type="button" data-rule-action="import">Import rules</button><input type="file" accept="application/json,.json" class="rule-import" hidden></div></header>
 <div class="rule-workspace"><aside class="rule-library" aria-label="Source spells"><label>Search spells<input class="rule-search" type="search" value="${escape(query)}" placeholder="Spell name or source"></label><label>Show<select class="rule-filter">${[['all','All source spells'],['2014','2014 rules'],['2024','2024 rules'],['saved','Saved rules']].map(([value,name])=>option(value,name,value===filter)).join('')}</select></label><p class="rule-search-count"></p><div class="rule-spell-list"></div></aside>
 <div class="rule-editor-main">${rule?`<header class="rule-selected-heading"><div><h2>${escape(rule.name)}</h2><p>${escape(selected.source)} · ${escape(rule.edition)} · ${rule.level?'Level '+rule.level:'Cantrip'}${saved[rule.reference]?' · Saved version available':' · Unsaved starter rules'}</p></div>${check('Enabled','enabled',rule.enabled)}</header>
 <details class="rule-source"><summary>Read source spell</summary>${formatEntries(selected.entries)}${formatEntries(selected.entriesHigherLevel)}</details>
 <fieldset><legend>Targeting & casting</legend><div class="rule-fields">${select('Casting cost','timing',rule.timing,[['action','Action'],['bonus','Bonus action']])}${select('Targeting','shape',rule.shape,[['target','One creature'],['self','Self'],['circle','Circle / cylinder'],['cone','Cone'],['line','Wall / line'],['ring','Ring wall'],['sphere','Movable sphere']])}${input('Range (ft)','range',rule.range)}${input(rule.shape==='cone'?'Cone length (ft)':'Radius (ft; sphere 0 = one square)','radius',rule.radius,{max:100})}${input('Wall length (ft)','length',rule.length,{max:120})}</div>${check('Uses a spell attack roll','attack',rule.attack)}</fieldset>
 <fieldset><legend>Duration & map effect</legend><div class="rule-fields">${input('Duration (seconds)','duration',rule.duration,{max:86400})}${input('Nearby distance (ft)','nearby',rule.nearby,{max:30})}${input('Sphere movement per bonus action (ft)','move',rule.move,{max:60})}</div><div class="rule-checks">${check('Leave a persistent area','persistent',rule.persistent)}${check('Requires concentration','concentration',rule.concentration)}${check('Ends after caster’s next turn','endNextTurn',rule.endNextTurn)}${check('Difficult terrain','difficult',rule.difficult)}${check('Blocks vision (not physical movement)','blocksVision',rule.blocksVision)}</div></fieldset>
 <div class="rule-effects">${effects()}</div><button class="button outline small" type="button" data-rule-action="add-effect">Add effect block</button>
 <p class="rule-validation" role="status"></p><div class="rule-buttons"><button type="button" class="button primary" data-rule-action="save">Save rules</button><button type="button" class="button outline" data-rule-action="starter">Restore starter</button>${saved[rule.reference]?'<button type="button" class="button outline" data-rule-action="delete">Remove saved override</button>':''}</div>
 <section class="rule-preview" aria-label="Spell test encounter"><h3>Test encounter</h3><p>Uses these draft rules against sample creatures. Your characters and rooms stay untouched.</p><canvas width="600" height="300" aria-label="Spell area preview"></canvas><div class="rule-buttons"><button type="button" class="button outline small" data-rule-action="test">Test cast</button><button type="button" class="button outline small" data-rule-action="next-turn">Advance turns</button><button type="button" class="button outline small" data-rule-action="test-move">Test entering area</button>${rule.shape==='sphere'?'<button type="button" class="button outline small" data-rule-action="test-ram">Test sphere ram</button>':''}</div><div class="rule-preview-results" role="log">No test run yet.</div></section>
 <section class="rule-publish"><h3>Apply saved library to a room</h3><p>New rooms use your saved library. Update an existing room here between encounters. Existing spell areas keep the rules they were cast with.</p><label>Adventure room<select class="rule-room"><option value="">Choose a saved room</option>${knownRooms().map(room=>option(room.id,room.name,false)).join('')}</select></label><button type="button" class="button outline small" data-rule-action="publish">Apply saved rules</button></section>`:'<p>Choose a source spell to begin.</p>'}
 <p class="rule-status" role="status"></p><p class="rule-editor-note">The editor supports the listed grid effects. Heights, vertical flight, unusual interactions and effects without a matching block still require manual adjudication. No scripts are executed.</p></div></div></section>`;
 library();summary();drawPreview();
 }
 function drawPreview(){const canvas=host.querySelector('.rule-preview canvas');if(!canvas||!rule)return;const c=canvas.getContext('2d'),size=25,map={cols:24,rows:12,size:25,width:600,height:300,regions:[],offsetX:0,offsetY:0},caster={x:2,y:6},square=rule.shape==='line'?{x:8,y:2}:{x:10,y:6},end={x:8,y:10},cells=customSpellCells(rule,caster,square,map,{end});c.clearRect(0,0,600,300);c.fillStyle='#14281f';c.fillRect(0,0,600,300);for(const cell of cells){const [x,y]=cell.split(':').map(Number);c.fillStyle=rule.difficult?'#6e7385aa':'#ac613b99';c.fillRect(x*size,y*size,size,size);}c.strokeStyle='#68836555';for(let x=0;x<=600;x+=size){c.beginPath();c.moveTo(x,0);c.lineTo(x,300);c.stroke();}for(let y=0;y<=300;y+=size){c.beginPath();c.moveTo(0,y);c.lineTo(600,y);c.stroke();}for(const [index,actor] of (preview?.battle.actors??[caster,{x:10,y:6},{x:11,y:7}]).entries()){c.beginPath();c.arc((actor.x+.5)*size,(actor.y+.5)*size,9,0,Math.PI*2);c.fillStyle=index?'#b65d51':'#68aa8b';c.fill();c.fillStyle='#fff';c.font='10px system-ui';c.textAlign='center';c.fillText(index?String(actor.hp??60):'C',(actor.x+.5)*size,(actor.y+.5)*size+3);}}
 function test(action){
  if(ruleProblems(rule).length){status(ruleProblems(rule).join(' '));return;}
  try{
   if(action==='test'||!preview){const battle=newBattle(),caster=makeActor({id:'preview-caster',name:'Test caster',side:'party',x:2,y:6,hp:60,maxHp:60,initiative:100,spellDC:15,spellAttack:7,slots:{[Math.max(1,rule.level)]:{current:3,maximum:3}}}),target=makeActor({id:'preview-target',name:'Test target',x:rule.shape==='line'?8:10,y:6,hp:60,maxHp:60,ac:12,saves:{dex:0}}),other=makeActor({id:'preview-other',name:'Nearby target',x:11,y:7,hp:60,maxHp:60,saves:{dex:2}}),map={cols:24,rows:12,size:25,width:600,height:300,offsetX:0,offsetY:0,regions:[]};battle.actors=[caster,target,other];battle.spellRules={[rule.reference]:structuredClone(rule)};startInitiative(battle,()=>.45);castSpell(battle,caster,target,{name:rule.name,key:rule.name.toLowerCase(),reference:rule.reference,edition:rule.edition,level:rule.level},rule.level,{map,square:rule.shape==='line'?{x:8,y:2}:{x:9,y:6},end:{x:8,y:10},hotSide:'left'},()=>.45);preview={battle,map,caster,target};}
   else if(action==='next-turn'){for(let i=0;i<3;i++)endTurn(preview.battle,()=>.45);}
   else if(action==='test-ram'){preview.battle.bonusUsed=false;const zone=preview.battle.spellZones?.find(zone=>zone.custom);moveCustomSphere(preview.battle,preview.caster,zone?.id,{x:preview.target.x,y:preview.target.y},preview.map,()=>.45);}
   else{preview.battle.round=0;preview.target.x=6;preview.target.y=6;exploreToken(preview.battle,preview.target,rule.shape==='line'?8:9,6,preview.map,()=>false);}
   const result=host.querySelector('.rule-preview-results');result.textContent=preview.battle.log.slice(-18).join('\n')+'\nSlots remaining: '+(preview.caster.slots[Math.max(1,rule.level)]?.current??'—');drawPreview();
  }catch(error){host.querySelector('.rule-preview-results').textContent=error.message;}
 }
 host.addEventListener('input',event=>{if(event.target.matches('.rule-search')){query=event.target.value;library();return;}const path=event.target.dataset.ruleField;if(!path)return;const parts=path.split('.');let value=rule;for(const part of parts.slice(0,-1))value=value[part];value[parts.at(-1)]=event.target.type==='checkbox'?event.target.checked:event.target.type==='number'?Number(event.target.value):event.target.value;retain();preview=null;summary();drawPreview();});
 host.addEventListener('change',event=>{if(event.target.matches('.rule-filter')){filter=event.target.value;library();}if(event.target.matches('.rule-import'))void(async()=>{try{const file=event.target.files[0];if(!file||file.size>1024*1024)throw Error('Choose a rules JSON file up to 1 MB.');importSpellRules(JSON.parse(await file.text()));saved=loadSpellRules();render();status('Rules imported. Rooms keep their current versions until you apply an update.');}catch(error){status(error.message);}})();});
 host.addEventListener('click',event=>{const choice=event.target.closest('[data-rule-select]');if(choice){const spell=catalog.find(spell=>ruleId(spell)===choice.dataset.ruleSelect);if(spell)choose(spell);return;}const control=event.target.closest('[data-rule-action]');if(!control)return;const action=control.dataset.ruleAction,index=Number(control.dataset.index),component=Number(control.dataset.component);
  try{
   if(action==='save'){const savedRule=saveSpellRule(rule);saved=loadSpellRules();rule=structuredClone(savedRule);retain();render();status('Saved. New rooms use this version. Apply the library below to update an existing room.');}
   else if(action==='starter'){rule=starterRule(selected);retain();render();}
   else if(action==='delete'){removeSpellRule(rule.reference);saved=loadSpellRules();delete drafts[rule.reference];rule=starterRule(selected);retain();render();status('Saved override removed. Existing rooms keep their saved copies.');}
   else if(action==='add-effect'){if(rule.effects.length>=12)throw Error('Use up to 12 effect blocks.');rule.effects.push(structuredClone(blankRule(selected).effects[0]));retain();render();}
   else if(action==='remove-effect'){rule.effects.splice(index,1);retain();render();}
   else if(action==='add-damage'){if(rule.effects[index].damage.length>=4)throw Error('Use up to four damage components.');rule.effects[index].damage.push({formula:'1d6',type:'fire',upcast:''});retain();render();}
   else if(action==='remove-damage'){rule.effects[index].damage.splice(component,1);retain();render();}
   else if(action==='export'){const blob=new Blob([JSON.stringify(loadSpellRules(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='wayfarer-spell-rules.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
   else if(action==='import')host.querySelector('.rule-import').click();
   else if(action==='publish')void(async()=>{const id=host.querySelector('.rule-room').value;if(!id){status('Choose a room.');return;}control.disabled=true;status('Updating room rules…');try{for(let attempt=0;attempt<3;attempt++){const snapshot=await readSession(id);if(snapshot.state.battle.round)throw Error('Finish this room’s combat before updating spell rules.');snapshot.state.battle.spellRules=structuredClone(loadSpellRules());const result=await writeSession(id,snapshot.revision,snapshot.state);if(!result.state){status('Room updated. Future casts use the saved library.');return;}}throw Error('The room is busy. Try again after the next action.');}catch(error){status(error.message);}finally{control.disabled=false;}})();
   else test(action);
  }catch(error){status(error.message);}
 });
 const first=catalog.find(spell=>spell.name==='Wall of Fire'&&spell.source==='PHB')??catalog[0];choose(first);
}
